// the measured returns for a program (by its index), or nullptr
inline const LoopSpec* loopFor (int prog) {
    static std::vector<const LoopSpec*> byProg = [] {
        std::vector<const LoopSpec*> r (programs().size(), nullptr);
        for (size_t i = 0; i < programs().size(); ++i) {
            const auto& p = programs()[i];
            const char* grp = (p.bank >= 33 && p.bank <= 37) ? "X" : (p.bank >= 27 && p.bank <= 31) ? "M" : (p.bank <= 17) ? "F" : nullptr;
            if (! grp) continue;
            for (auto& e : loopTable()) if (std::strcmp (e.grp, grp) == 0 && std::strcmp (e.name, p.name) == 0) { r[i] = &e.spec; break; }
        }
        return r;
    }();
    return prog >= 0 && prog < (int) byProg.size() ? byProg[(size_t) prog] : nullptr;
}

